gB4(){return"\u092f\u0939\u093e\u0901 \u0936\u0947\u092f\u0930 \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u091c\u0935\u093e\u092c \u0915\u0949\u092a\u0940 \u0915\u0930 \u0932\u0947\u0902\u0964"},
gRS(){return"\u091c\u0935\u093e\u092c \u0926\u0947\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0941\u091b \u0928\u0939\u0940\u0902"},
gmq(a){return"\u092c\u0902\u0926 \u0915\u0930\u0947\u0902"},
gRy(){return"\u092f\u0939 \u0938\u0902\u0926\u0947\u0936 \u0905\u092c \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 ReplyMate \u0938\u0902\u0926\u0947\u0936 \u0915\u0947\u0935\u0932 \u092e\u0947\u092e\u094b\u0930\u0940 \u092e\u0947\u0902 \u0930\u0916\u0924\u093e \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u092a\u0948\u0928\u0932 \u092c\u0902\u0926 \u0939\u094b\u0924\u0947 \u0939\u0940 \u092f\u093e \u0910\u092a \u0930\u0941\u0915\u0924\u0947 \u0939\u0940 \u0935\u0939 \u091a\u0932\u093e \u091c\u093e\u0924\u093e \u0939\u0948\u0964 \u0905\u0917\u0932\u0947 \u0938\u0902\u0926\u0947\u0936 \u0915\u093e \u0907\u0902\u0924\u091c\u093c\u093e\u0930 \u0915\u0930\u0947\u0902, \u092f\u093e \u0915\u0902\u092a\u094b\u091c\u093c\u0930 \u092e\u0947\u0902 \u092a\u093e\u0920 \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u0947\u0902\u0964"},
gSo(){return"\u091c\u093f\u0938 \u0938\u0902\u0926\u0947\u0936 \u0915\u093e \u091c\u0935\u093e\u092c \u091a\u093e\u0939\u093f\u090f \u0909\u0938\u0947 \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u0947\u0902"},
gRN(){return"\u0907\u0938 \u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u092e\u0947\u0902 \u0915\u094b\u0908 \u0938\u0902\u0926\u0947\u0936 \u092a\u093e\u0920 \u0928\u0939\u0940\u0902 \u0925\u093e\u0964 \u0928\u0940\u091a\u0947 Paste \u0938\u0947 \u0916\u0941\u0926 \u0915\u0941\u091b \u0932\u093f\u0916\u0915\u0930 \u091c\u0935\u093e\u092c \u0926\u0947\u0902\u0964"},
gSn(){return"\u092a\u0947\u0938\u094d\u091f"},
gO5(){return"\u0907\u0938 \u0907\u0902\u0938\u094d\u091f\u0949\u0932 \u092a\u0930 AI \u0915\u0949\u0928\u094d\u092b\u093c\u093f\u0917\u0930 \u0928\u0939\u0940\u0902 \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u091c\u0928\u0930\u0947\u091f \u0915\u0930\u0928\u0947 \u092a\u0930 \u0928\u0915\u0932\u0940 \u091c\u0935\u093e\u092c \u0915\u0947 \u092c\u091c\u093e\u092f \u092f\u0939\u0940 \u092c\u0924\u093e\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964"},
gAy(){return"\u092c\u0928 \u0930\u0939\u093e \u0939\u0948\u2026"},
gIp(){return"\u0938\u0941\u091d\u093e\u0935 \u092c\u0928\u093e\u090f\u0901"},
gRM(){return"\u0915\u094b\u0908 \u0938\u0902\u0926\u0947\u0936 \u0915\u0948\u092a\u094d\u091a\u0930 \u0928\u0939\u0940\u0902 \u0939\u0941\u0906\u0964 ReplyMate \u0938\u0902\u0926\u0947\u0936 \u0915\u0947\u0935\u0932 \u0910\u092a \u0916\u0941\u0932\u093e \u0930\u0939\u0928\u0947 \u0924\u0915 \u0930\u0916\u0924\u093e \u0939\u0948, \u0907\u0938\u0932\u093f\u090f \u0928\u0940\u091a\u0947 \u092a\u093e\u0920 \u092a\u0947\u0938\u094d\u091f \u0915\u0930\u0915\u0947 \u0916\u0941\u0926 \u091c\u0935\u093e\u092c \u0926\u0947\u0902\u0964"},
gRL(){return"\u0928\u092f\u093e \u091c\u0935\u093e\u092c"},
gRz(){return"\u0938\u0902\u0926\u0947\u0936"},
gON(a){return"\u0939\u091f\u093e\u090f\u0901"},
