gOz(){return"\u092b\u093c\u094d\u0932\u094b\u091f\u093f\u0902\u0917 \u0930\u093f\u092a\u094d\u0932\u093e\u0908 \u092c\u092c\u0932"},
gTl(a){return"\u0930\u0940\u092b\u093c\u094d\u0930\u0947\u0936"},
gTp(){return"\u0939\u093e\u0932 \u0915\u0940 \u091a\u0948\u091f \u092f\u093e\u0926 \u0930\u0916\u0947\u0902"},
gTq(){return"\u0939\u0930 \u091a\u0948\u091f \u0915\u0947 \u092a\u093f\u091b\u0932\u0947 \u0915\u0941\u091b \u0938\u0902\u0926\u0947\u0936 - \u0914\u0930 \u0906\u092a\u0915\u0947 \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u093f\u090f \u091c\u0935\u093e\u092c - \u092f\u093e\u0926 \u0930\u0916\u0924\u093e \u0939\u0948, \u0924\u093e\u0915\u093f \u0905\u0917\u0932\u093e \u0921\u094d\u0930\u093e\u092b\u093c\u094d\u091f \u092c\u093e\u0924\u091a\u0940\u0924 \u0915\u094b \u0906\u0917\u0947 \u092c\u0922\u093c\u093e\u090f \u0914\u0930 \u0906\u092a \u091c\u0948\u0938\u093e \u0932\u0917\u0947\u0964 \u0915\u0947\u0935\u0932 \u0907\u0938\u0940 \u0921\u093f\u0935\u093e\u0907\u0938 \u092a\u0930, \u0915\u0939\u0940\u0902 \u0905\u092a\u0932\u094b\u0921 \u0928\u0939\u0940\u0902, \u092c\u0948\u0915\u0905\u092a \u092e\u0947\u0902 \u092d\u0940 \u0928\u0939\u0940\u0902\u0964 \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u092c\u0902\u0926; \u092c\u0902\u0926 \u0915\u0930\u0928\u0947 \u092a\u0930 \u0938\u092c \u092e\u093f\u091f \u091c\u093e\u0924\u093e \u0939\u0948\u0964"},
gGQ(){return"\u0905\u092d\u0940 \u0915\u0941\u091b \u092f\u093e\u0926 \u0928\u0939\u0940\u0902 \u0930\u0916\u093e \u0917\u092f\u093e\u0964 \u0915\u093f\u0938\u0940 \u091a\u0948\u091f \u0915\u093e \u091c\u0935\u093e\u092c \u0916\u094b\u0932\u0947\u0902, \u0935\u0939 \u092f\u0939\u093e\u0901 \u0926\u093f\u0916\u0947\u0917\u093e\u0964"},
gQc(){return"\u092f\u0939 \u091a\u0948\u091f \u092d\u0941\u0932\u093e \u0926\u0947\u0902"},
gPv(){return"\u092f\u093e\u0926 \u0930\u0916\u0940 \u0938\u092d\u0940 \u091a\u0948\u091f \u0939\u091f\u093e\u090f\u0901"},
gPw(){return"\u092f\u093e\u0926 \u0930\u0916\u0940 \u0938\u092d\u0940 \u091a\u0948\u091f \u0939\u091f\u093e\u090f\u0901?"},
gPu(){return"\u0907\u0938 \u0910\u092a \u0928\u0947 \u091c\u094b \u092d\u0940 \u0938\u0902\u0926\u0947\u0936 \u092f\u093e\u0926 \u0930\u0916\u093e \u0925\u093e, \u0935\u0939 \u0907\u0938 \u0921\u093f\u0935\u093e\u0907\u0938 \u0938\u0947 \u0939\u091f \u091c\u093e\u090f\u0917\u093e\u0964 \u091c\u0935\u093e\u092c\u094b\u0902 \u092a\u0930 \u0915\u094b\u0908 \u0905\u0938\u0930 \u0928\u0939\u0940\u0902 - \u0915\u0947\u0935\u0932 \u0935\u0939\u0940 \u092e\u093f\u091f\u0947\u0917\u093e \u091c\u094b \u091c\u0935\u093e\u092c \u0932\u093f\u0916\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0930\u0916\u093e \u0917\u092f\u093e \u0925\u093e\u0964"},
gR7(){return"\u0930\u0916\u0947\u0902"},
gvM(a){return"\u0939\u091f\u093e\u090f\u0901"},
Jq(a){return"\u0938\u0941\u091d\u093e\u0935"},
Iq(a){return""+a+" \u0938\u0941\u091d\u093e\u0935 \u092c\u0928\u093e\u090f\u0901"},
