gO8(){return"\u0910\u092a \u0939\u093f\u0902\u0926\u0940 \u092e\u0947\u0902 \u091a\u0932\u0947\u0917\u093e\u0964 \u091c\u0935\u093e\u092c \u092b\u093f\u0930 \u092d\u0940 \u090a\u092a\u0930 \u091a\u0941\u0928\u0940 \u0917\u0908 \u091c\u0935\u093e\u092c \u0915\u0940 \u092d\u093e\u0937\u093e \u092e\u0947\u0902 \u092c\u0928\u0947\u0902\u0917\u0947\u0964"},
gS4(){return"\u0906\u092a\u0915\u093e \u090f\u0906\u0908 \u0930\u093f\u092a\u094d\u0932\u093e\u0908 \u0938\u0939\u093e\u092f\u0915"},
gSg(){return"ReplyMate AI"},
gSf(){return"\u0906\u092a\u0915\u0940 \u092d\u093e\u0937\u093e \u092e\u0947\u0902 \u0938\u094b\u091a-\u0938\u092e\u091d\u0915\u0930 \u0932\u093f\u0916\u093e \u091c\u0935\u093e\u092c,\\n\u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u0939\u092e\u0947\u0936\u093e \u0906\u092a\u0915\u0947 \u092a\u093e\u0938\u0964"},
gS8(){return"\u091c\u0935\u093e\u092c \u091c\u093f\u0938\u0947 \u0906\u092a \u092e\u0902\u091c\u093c\u0942\u0930 \u0915\u0930\u0947\u0902, \u0939\u092e\u0947\u0936\u093e"},
gS7(){return"ReplyMate \u091c\u0935\u093e\u092c \u0938\u0941\u091d\u093e\u0924\u093e \u0939\u0948\u0964 \u0906\u092a \u0926\u0947\u0916\u0915\u0930, \u092c\u0926\u0932\u0915\u0930 \u092d\u0947\u091c\u0924\u0947 \u0939\u0948\u0902 - \u0910\u092a \u0916\u0941\u0926 \u0915\u0941\u091b \u0928\u0939\u0940\u0902 \u092d\u0947\u091c\u0924\u093e\u0964"},
gSc(){return"\u0928\u094b\u091f\u093f\u092b\u093f\u0915\u0947\u0936\u0928 \u0938\u0947 \u0939\u0940 \u0915\u093e\u092e \u0915\u0930\u0924\u093e \u0939\u0948"},
